/**
 * WinCC Unified HMI screen item type catalog (V20).
 *
 * Every concrete subclass of Siemens.Engineering.HmiUnified.UI.Base.HmiScreenItemBase
 * with its publicly writable properties. Used by Pac-Forge to:
 *   1. Validate item type names before emitting payloads
 *   2. Check attribute names for each type
 *   3. Tell the bridge which .NET Type to pass to CreateCompositeItem<T>() via fullName
 *
 * Generated by bridge/reflect-screen-items.ps1 + bridge/emit-item-types.ps1.
 * Re-run both when upgrading to a newer TIA Portal version.
 */

export type HmiItemCategory = "Shapes" | "Widgets" | "Controls" | "Screens" | "Base";

export interface HmiItemPropertySpec {
  /** PascalCase Openness attribute name, e.g. BackColor, Width, IsEnabled */
  name: string;
  /** .NET type name: Color, UInt32, Boolean, HmiFillPattern, ... */
  typeName: string;
  isEnum: boolean;
  enumValues: string[];
}

export interface HmiItemTypeSpec {
  /** Short type name, e.g. HmiRectangle */
  name: string;
  /** Fully qualified .NET type name, used by the bridge for generic dispatch */
  fullName: string;
  namespace: string;
  category: HmiItemCategory;
  properties: HmiItemPropertySpec[];
}

