/** Look up a type spec by short name. */
export function getItemTypeSpec(name: string): HmiItemTypeSpec | null {
  return HMI_ITEM_TYPES[name] ?? null;
}

/** Return the set of valid attribute names for a given item type, or empty if unknown. */
export function getValidAttributes(typeName: string): Set<string> {
  const spec = getItemTypeSpec(typeName);
  if (!spec) return new Set();
  return new Set(spec.properties.map((p) => p.name));
}

/** Check whether an attribute name is valid for a given item type. */
export function isValidAttribute(typeName: string, attrName: string): boolean {
  return getValidAttributes(typeName).has(attrName);
}

/** List all item types in a given category. */
export function getItemTypesByCategory(category: HmiItemCategory): HmiItemTypeSpec[] {
  return Object.values(HMI_ITEM_TYPES).filter((t) => t.category === category);
}

